put('webapp/src/components/NunoContribution.tsx', '''import React,{useState} from 'react'\nimport {validateNunoConsent,type UserConsent} from '../api'\nconst NunoContribution:React.FC=()=>{const[age,setAge]=useState('');const[consent,setConsent]=useState(false);const[withdrawal,setWithdrawal]=useState(false);const[mode,setMode]=useState<UserConsent['identityMode']>('anonymous');const candidate:UserConsent={age:Number(age),consentPublic:consent,identityMode:mode,withdrawalAcknowledged:withdrawal,humanReviewRequired:true};const eligible=validateNunoConsent(candidate);return <section className="nuno-contribution" aria-labelledby="nuno-title"><h2 id="nuno-title">Nuno / Escuta</h2><p>A contribuição só segue para revisão humana quando a pessoa tem 13 anos ou mais e presta consentimento explícito.</p><label>Idade <input inputMode="numeric" value={age} onChange={e=>setAge(e.target.value)}/></label><label>Identificação <select value={mode} onChange={e=>setMode(e.target.value as UserConsent['identityMode'])}><option value="anonymous">Anónimo</option><option value="pseudonym">Pseudónimo</option><option value="name">Nome</option></select></label><label><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/> Autorizo o envio para revisão humana.</label><label><input type="checkbox" checked={withdrawal} onChange={e=>setWithdrawal(e.target.checked)}/> Compreendo que posso pedir retirada.</label><button type="button" disabled={!eligible}>Enviar para revisão humana</button></section>}\nexport default NunoContribution\n''')
