put('ia-milk/security.py', '''import re\nfrom dataclasses import dataclass\nfrom typing import Iterable\nSECRET=[re.compile(r"-----BEGIN (?:RSA |OPENSSH |EC )?PRIVATE KEY-----",re.I),re.compile(r"\\b(?:password|senha|secret|token|api[_-]?key|credential)\\s*[:=]",re.I),re.compile(r"\\bsk-[A-Za-z0-9_-]{20,}\\b")]\nSENSITIVE=[re.compile(r"\\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}\\b",re.I)]\n@dataclass(frozen=True)\nclass SafetyDecision: allowed_for_rag:bool; reason:str\ndef classify_text(text:str)->SafetyDecision:\n    if any(p.search(text) for p in SECRET):return SafetyDecision(False,'SECRET_OR_CREDENTIAL')\n    if any(p.search(text) for p in SENSITIVE):return SafetyDecision(False,'POTENTIAL_PERSONAL_DATA_REQUIRES_HUMAN_REVIEW')\n    return SafetyDecision(True,'ALLOWED')\ndef filter_allowed(texts:Iterable[str])->list[str]:return[t for t in texts if classify_text(t).allowed_for_rag]\n''')
put('ia-milk/chunking.py', '''import hashlib\nfrom dataclasses import dataclass\n@dataclass(frozen=True)\nclass Chunk: source_id:str; index:int; text:str; sha256:str\ndef chunk_text(source_id:str,text:str,words_per_chunk:int=350,overlap:int=40)->list[Chunk]:\n    if words_per_chunk<=0 or overlap<0 or overlap>=words_per_chunk:raise ValueError('invalid chunk parameters')\n    words=text.split();out=[];start=0;idx=0\n    while start<len(words):\n        end=min(start+words_per_chunk,len(words));body=' '.join(words[start:end]);out.append(Chunk(source_id,idx,body,hashlib.sha256(body.encode()).hexdigest()))\n        if end==len(words):break\n        start=end-overlap;idx+=1\n    return out\n''')
put('ia-milk/index.py', '''import math,re\nfrom collections import Counter\nfrom dataclasses import dataclass\nfrom chunking import Chunk\nTOKEN=re.compile(r"[\\wÀ-ÿ]+",re.UNICODE)\ndef tokens(t:str)->list[str]:return[x.lower() for x in TOKEN.findall(t)]\n@dataclass\nclass Hit:chunk:Chunk;score:float\nclass LexicalIndex:\n    def __init__(self):self.chunks=[];self.df=Counter()\n    def add(self,chunks):\n        for c in chunks:self.chunks.append(c);self.df.update(set(tokens(c.text)))\n    def search(self,query:str,limit:int=8):\n        q=Counter(tokens(query));n=max(1,len(self.chunks));hits=[]\n        for c in self.chunks:\n            d=Counter(tokens(c.text));s=sum(qf*d[t]*math.log((n+1)/(self.df[t]+1)+1) for t,qf in q.items() if d[t])\n            if s>0:hits.append(Hit(c,s))\n        return sorted(hits,key=lambda h:(-h.score,h.chunk.source_id,h.chunk.index))[:limit]\n''')
put('ia-milk/retrieval.py', '''from dataclasses import dataclass\nfrom index import LexicalIndex\n@dataclass(frozen=True)\nclass Citation:source_id:str;chunk_index:int;sha256:str\n@dataclass\nclass RetrievalResult:context:list[str];citations:list[Citation]\ndef retrieve(index:LexicalIndex,query:str,limit:int=6)->RetrievalResult:\n    hits=index.search(query,limit);return RetrievalResult([h.chunk.text for h in hits],[Citation(h.chunk.source_id,h.chunk.index,h.chunk.sha256) for h in hits])\n''')
put('ia-milk/mistral_embeddings.py', '''import json,os,urllib.request\nfrom typing import Sequence\nclass MistralEmbeddings:\n    def __init__(self,model='mistral-embed',endpoint='https://api.mistral.ai/v1/embeddings'):self.model=model;self.endpoint=endpoint\n    def embed(self,texts:Sequence[str])->list[list[float]]:\n        if not texts:return[]\n        key=os.getenv('MISTRAL_API_KEY')\n        if not key:raise RuntimeError('MISTRAL_API_KEY is not configured; lexical retrieval remains available')\n        req=urllib.request.Request(self.endpoint,data=json.dumps({'model':self.model,'input':list(texts)}).encode(),method='POST',headers={'Authorization':f'Bearer {key}','Content-Type':'application/json'})\n        with urllib.request.urlopen(req,timeout=30) as r:body=json.loads(r.read().decode())\n        return[item['embedding'] for item in body['data']]\n''')
put('ia-milk/ingest.py', '''from pathlib import Path\nfrom chunking import chunk_text\nfrom security import classify_text\nTEXT_EXTENSIONS={'.txt','.md','.markdown','.json','.csv','.tsv','.html','.htm'}\ndef read_export(path):\n    p=Path(path)\n    if p.suffix.lower() not in TEXT_EXTENSIONS:raise ValueError('binary/native document must be exported to a textual preservation format before IA MILK ingestion')\n    return p.read_text(encoding='utf-8',errors='strict')\ndef ingest_file(path,source_id=None):\n    p=Path(path);text=read_export(p);decision=classify_text(text)\n    if not decision.allowed_for_rag:raise ValueError(decision.reason)\n    return chunk_text(source_id or p.name,text)\n''')
put('ia-milk/router.py', '''from dataclasses import dataclass\nfrom typing import Literal\nFunctionName=Literal['curadoria','territorial','migracao','webapp']\n@dataclass(frozen=True)\nclass RouteDecision:function:FunctionName;requires_human_validation:bool;source_mutation_allowed:bool=False\ndef route(function:FunctionName)->RouteDecision:\n    if function not in ('curadoria','territorial','migracao','webapp'):raise ValueError('unknown IA MILK function')\n    return RouteDecision(function,function in ('curadoria','territorial'),False)\n''')
put('ia-milk/evals.py', '''from security import classify_text\nPUBLIC_SEQUENCE=('cosmicoxes','copernico','cosmic-flow','selo-atlas','fuco','galeria-diletante','milks-territoriais','inflar','particulas','papel-rasgado','brincar-convite-sorte','nuno')\ndef eval_cosmic_distinction():return PUBLIC_SEQUENCE.index('cosmicoxes')!=PUBLIC_SEQUENCE.index('cosmic-flow')\ndef eval_nuno_gate(age,consent,withdrawal,human_review):return age>=13 and consent and withdrawal and human_review\ndef eval_no_invisible_public(payload):\n    forbidden={'camada_invisivel','invisibleLayer','mycorrhiza','micorriza','credential','password','secret'}\n    def walk(v):\n        if isinstance(v,dict):return all(k not in forbidden and walk(x) for k,x in v.items())\n        if isinstance(v,list):return all(walk(x) for x in v)\n        return True\n    return walk(payload)\ndef eval_no_secret_training(text):return classify_text(text).allowed_for_rag\n''')
put('ia-milk/memory.py', '''import hashlib,json,uuid\nfrom dataclasses import dataclass,field,asdict\nfrom datetime import datetime,timezone\nfrom typing import Any\n@dataclass(frozen=True)\nclass Receipt:\n    operation:str;source:str;target:str|None=None;metadata:dict[str,Any]=field(default_factory=dict);provenance:tuple[str,...]=();id:str=field(default_factory=lambda:str(uuid.uuid4()));timestamp:str=field(default_factory=lambda:datetime.now(timezone.utc).isoformat())\n    def digest(self):return hashlib.sha256(json.dumps(asdict(self),sort_keys=True,ensure_ascii=False).encode()).hexdigest()\nclass MemoryManager:\n    def __init__(self):self.episodic={};self.procedural={};self.receipts=[]\n    def log_episodic(self,event_id,data,source,provenance=()):self.episodic[event_id]=data;r=Receipt('LOG_EPISODIC',source,event_id,{'keys':sorted(data)},provenance);self.receipts.append(r);return r\n    def log_procedural(self,procedure_id,steps,source,provenance=()):self.procedural[procedure_id]=steps;r=Receipt('LOG_PROCEDURAL',source,procedure_id,{'step_count':len(steps)},provenance);self.receipts.append(r);return r\n''')
put('ia-milk/test_ia_milk.py', '''from chunking import chunk_text\nfrom index import LexicalIndex\nfrom retrieval import retrieve\nfrom security import classify_text\nfrom evals import eval_cosmic_distinction,eval_nuno_gate,eval_no_invisible_public\nfrom router import route\ndef test_chunking_deterministic():\n a=chunk_text('x','um dois tres quatro',3,1);b=chunk_text('x','um dois tres quatro',3,1);assert[(x.text,x.sha256) for x in a]==[(x.text,x.sha256) for x in b]\ndef test_secret_block():assert not classify_text('password=abc').allowed_for_rag\ndef test_retrieval_citations():\n idx=LexicalIndex();idx.add(chunk_text('fonte-1','festa memória freguesia território'));r=retrieve(idx,'memória freguesia');assert r.context and r.citations[0].source_id=='fonte-1'\ndef test_invariants():assert eval_cosmic_distinction() and not eval_nuno_gate(12,True,True,True) and eval_nuno_gate(13,True,True,True) and not eval_no_invisible_public({'camada_invisivel':{'x':1}})\ndef test_router_read_only():assert route('migracao').source_mutation_allowed is False\n''')
put('ia-milk/README.md', '''# IA MILK — núcleo RAG executável\n\nEstado: engenharia funcional e avaliação local. **Não existe declaração de fine-tuning concluído.**\n\nFluxo obrigatório: corpus autorizado/exportado → classificação de segurança → chunking determinístico + SHA-256 → índice lexical local → retrieval com citações → inferência Mistral opcional → avaliação → validação humana quando aplicável → receipt/proveniência.\n\nCredenciais, segredos e potenciais dados pessoais ficam fora do corpus RAG por defeito. O Drive de origem permanece read-only. Funções: `curadoria`, `territorial`, `migracao`, `webapp`. Nenhuma recebe autorização implícita para alterar a origem. Fine-tuning futuro exige dataset explícito, revisão de direitos/RGPD, split de avaliação, baseline RAG e aprovação humana.\n''')
